 * All rights reserved.
 *
 * OHOS AArch64 dual-libc++ exception/RTTI isolation version script.
 *
 * On OHOS the musl loader force-maps the system "__h2" libc++
 * (/system/lib64/chipset-sdk-sp/libc++.so) ahead of the runtime "__n1"
 * libc++_shared.so via the chipset-sdk-sp startup dependency set (libhilog,
 * libbegetutil, ...). Both libc++ export IDENTICAL un-namespaced
 * exception/RTTI runtime symbols (__cxa_*, operator new/delete,
 * __gxx_personality_v0, _ZTISt12length_error, _ZTISt9bad_alloc, ...).
 *
 * Because the system __h2 libc++ loads first, libfastdds.so otherwise binds
 * its exception-throwing / type_info runtime to __h2 while its std::__n1
 * containers run on __n1 -> a cross-namespace EH/RTTI mismatch that surfaces
 * as a spurious std::length_error("vector") / std::bad_alloc inside
 * create_participant -> PDP discovery construction.
 *
 * Marking these runtime symbols local forces every intra-library reference to
 * resolve to libfastdds's own __n1-built copies (reinforced by -Bsymbolic),
 * eliminating the interposition. The fastdds public API and the __n1 std
 * symbols it legitimately exports remain global.
 *
 * Keep this isolation list aligned with the dual-libc++ failure mode described
 * above and validate participant creation on every supported OHOS toolchain.
 */
{
  local:
    /* Itanium C++ ABI exception runtime */
    __cxa_throw;
    __cxa_rethrow;
    __cxa_begin_catch;
    __cxa_end_catch;
    __cxa_allocate_exception;
    __cxa_free_exception;
    __cxa_allocate_dependent_exception;
    __cxa_free_dependent_exception;
    __cxa_get_exception_ptr;
    __cxa_call_unexpected;
    __cxa_current_exception_type;
    __cxa_bad_cast;
    __cxa_bad_typeid;
    __cxa_throw_bad_array_new_length;
    __cxa_guard_acquire;
    __cxa_guard_release;
    __cxa_guard_abort;
    __cxa_pure_virtual;
    __cxa_deleted_virtual;
    __cxa_demangle;

    /* GCC/LLVM personality + unwinder shims */
    __gxx_personality_v0;
    __cxa_call_terminate;

    /* operator new / delete (all overloads) */
    _Znwm;
    _Znam;
    _ZdlPv;
    _ZdaPv;
    _ZdlPvm;
    _ZdaPvm;
    _ZdlPvSt11align_val_t;
    _ZdaPvSt11align_val_t;
    _ZnwmRKSt9nothrow_t;
    _ZnamRKSt9nothrow_t;
    _ZnwmSt11align_val_t;
    _ZnamSt11align_val_t;

    /* type_info objects / vtables / typeid strings for the exact std
     * exception types fastdds throws/catches across the boundary */
    _ZTISt9exception;
    _ZTISt9bad_alloc;
    _ZTISt12length_error;
    _ZTISt13runtime_error;
    _ZTISt11logic_error;
    _ZTISt12out_of_range;
    _ZTISt16invalid_argument;
    _ZTISt13bad_exception;
    _ZTSSt9exception;
    _ZTSSt9bad_alloc;
    _ZTSSt12length_error;
    _ZTSSt13runtime_error;
    _ZTSSt11logic_error;
    _ZTSSt12out_of_range;
    _ZTSSt16invalid_argument;
    _ZTVSt9exception;
    _ZTVSt9bad_alloc;
    _ZTVSt12length_error;
    _ZTVSt13runtime_error;
    _ZTVSt11logic_error;
};
